"use client";

/**
 * Cendaro — Catalog Import: Step 3 — Validation Preview (Zero-Template + RAG)
 *
 * Shows validated rows with status filtering, inline SKU editing (for auto-generated
 * or duplicate SKUs), 1-click semantic duplicate resolution, and error details.
 */
import { useMemo, useRef, useState } from "react";
import { useVirtualizer } from "@tanstack/react-virtual";

import type { IconName } from "@cendaro/ui/icons";
import { Icon, Icons } from "@cendaro/ui/icons";
import { StatusPill } from "@cendaro/ui/status-pill";

import type { CatalogAiSummary } from "../hooks/use-parse-catalog-file";
import type { ValidatedCatalogRow } from "../lib/catalog-validators";

type StatusFilter = "all" | "valid" | "warning" | "error";

interface ValidationPreviewProps {
  validatedRows: ValidatedCatalogRow[];
  validCount: number;
  warningCount: number;
  errorCount: number;
  aiSummary?: CatalogAiSummary;
  onUpdateRowSku?: (rowNumber: number, newSku: string) => void;
  onProceed: () => void;
  onBack: () => void;
}

export function ValidationPreview({
  validatedRows,
  validCount,
  warningCount,
  errorCount,
  aiSummary,
  onUpdateRowSku,
  onProceed,
  onBack,
}: ValidationPreviewProps) {
  const [filter, setFilter] = useState<StatusFilter>("all");
  const [editingRowNumber, setEditingRowNumber] = useState<number | null>(null);
  const [skuDraft, setSkuDraft] = useState("");

  const parentRef = useRef<HTMLDivElement>(null);

  const filteredRows = useMemo(() => {
    if (filter === "all") return validatedRows;
    return validatedRows.filter((r) => r.status === filter);
  }, [validatedRows, filter]);

  const rowVirtualizer = useVirtualizer({
    count: filteredRows.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 44,
    overscan: 10,
  });

  const virtualRows = rowVirtualizer.getVirtualItems();
  const totalSize = rowVirtualizer.getTotalSize();

  const firstRow = virtualRows[0];
  const lastRow = virtualRows[virtualRows.length - 1];

  const paddingTop = firstRow ? firstRow.start : 0;
  const paddingBottom = lastRow ? totalSize - lastRow.end : 0;

  const processableCount = validCount + warningCount;

  const commitSkuEdit = (rowNumber: number) => {
    const trimmed = skuDraft.trim().toUpperCase();
    if (trimmed && onUpdateRowSku) {
      onUpdateRowSku(rowNumber, trimmed);
    }
    setEditingRowNumber(null);
    setSkuDraft("");
  };

  const statCards: {
    key: StatusFilter;
    label: string;
    count: number;
    color: string;
    icon: IconName;
  }[] = [
    {
      key: "all",
      label: "Total",
      count: validatedRows.length,
      color: "text-foreground bg-muted/50",
      icon: "List",
    },
    {
      key: "valid",
      label: "Válidas",
      count: validCount,
      color:
        "text-emerald-700 bg-emerald-50 dark:text-emerald-400 dark:bg-emerald-900/20",
      icon: "CheckCircle",
    },
    {
      key: "warning",
      label: "Advertencias",
      count: warningCount,
      color:
        "text-amber-700 bg-amber-50 dark:text-amber-400 dark:bg-amber-900/20",
      icon: "Warning",
    },
    {
      key: "error",
      label: "Errores",
      count: errorCount,
      color: "text-red-700 bg-red-50 dark:text-red-400 dark:bg-red-900/20",
      icon: "Error",
    },
  ];

  return (
    <div className="space-y-6">
      {/* Zero-Template AI + RAG summary banner */}
      {aiSummary &&
        (aiSummary.templateProfileHits > 0 ||
          aiSummary.aiInferredSheets > 0 ||
          aiSummary.pdfFilesExtracted > 0 ||
          aiSummary.autoGeneratedSkus > 0) && (
          <div className="border-border bg-card flex flex-wrap items-center justify-between gap-2 border px-4 py-3 text-xs">
            <div className="flex items-center gap-2">
              <Icons.SmartToy className="text-status-info-fg size-4 shrink-0" />
              <span className="text-foreground font-medium">
                Resumen IA + Catálogo RAG:
              </span>
              <span className="text-muted-foreground">
                Haz clic en cualquier SKU para editarlo antes de continuar.
              </span>
            </div>
            <div className="flex flex-wrap items-center gap-1.5">
              {aiSummary.templateProfileHits > 0 && (
                <StatusPill tone="success">
                  {aiSummary.templateProfileHits} huella(s) recordada(s)
                </StatusPill>
              )}
              {aiSummary.aiInferredSheets > 0 && (
                <StatusPill tone="info">
                  {aiSummary.aiInferredSheets} mapeada(s) con IA
                </StatusPill>
              )}
              {aiSummary.pdfFilesExtracted > 0 && (
                <StatusPill tone="info">
                  {aiSummary.pdfFilesExtracted} PDF extraído(s)
                </StatusPill>
              )}
              {aiSummary.autoGeneratedSkus > 0 && (
                <StatusPill tone="warning">
                  {aiSummary.autoGeneratedSkus} SKU(s) sugeridos
                </StatusPill>
              )}
            </div>
          </div>
        )}

      {/* Stat cards */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        {statCards.map((card) => (
          <button
            type="button"
            key={card.key}
            onClick={() => setFilter(card.key)}
            className={`border-border border p-3 text-left transition-colors ${card.color} ${
              filter === card.key
                ? "border-foreground/60 font-medium"
                : "hover:border-foreground/30"
            }`}
          >
            <div className="flex items-center gap-2">
              <Icon name={card.icon} className="size-4" />
              <span className="font-mono text-xl font-medium tabular-nums">
                {card.count}
              </span>
            </div>
            <p className="mt-1 text-xs font-medium opacity-80">{card.label}</p>
          </button>
        ))}
      </div>

      {/* Data table */}
      <div className="border-border bg-card overflow-hidden border">
        <div ref={parentRef} className="max-h-100 overflow-auto">
          <table className="w-full text-sm">
            <thead className="bg-muted/50 sticky top-0 z-10">
              <tr>
                <th className="px-3 py-2 text-left font-medium">#</th>
                <th className="px-3 py-2 text-left font-medium">Estado</th>
                <th className="px-3 py-2 text-left font-medium">SKU</th>
                <th className="px-3 py-2 text-left font-medium">Nombre</th>
                <th className="px-3 py-2 text-left font-medium">Categoría</th>
                <th className="px-3 py-2 text-left font-medium">Marca</th>
                <th className="px-3 py-2 text-left font-medium">Costo</th>
                <th className="px-3 py-2 text-left font-medium">Mensajes</th>
              </tr>
            </thead>
            <tbody className="divide-border divide-y">
              {paddingTop > 0 && (
                <tr>
                  <td colSpan={8} style={{ height: `${paddingTop}px` }} />
                </tr>
              )}
              {virtualRows.map((virtualRow) => {
                const row = filteredRows[virtualRow.index];
                if (!row) return null;
                const isEditingSku = editingRowNumber === row.rowNumber;
                const duplicateMatchSku =
                  row.semanticMatch?.classification === "possible_duplicate"
                    ? row.semanticMatch.matchedSku
                    : null;

                return (
                  <tr
                    key={virtualRow.key}
                    ref={rowVirtualizer.measureElement}
                    data-index={virtualRow.index}
                    className={`hover:bg-muted/20 transition-colors ${
                      row.status === "error"
                        ? "bg-red-50/50 dark:bg-red-900/5"
                        : row.status === "warning"
                          ? "bg-amber-50/50 dark:bg-amber-900/5"
                          : ""
                    }`}
                  >
                    <td className="text-muted-foreground px-3 py-2 text-xs">
                      {row.rowNumber}
                    </td>
                    <td className="px-3 py-2">
                      <Icon
                        name={
                          row.status === "valid"
                            ? "CheckCircle"
                            : row.status === "warning"
                              ? "Warning"
                              : "Error"
                        }
                        className={`size-4 ${
                          row.status === "valid"
                            ? "text-emerald-500"
                            : row.status === "warning"
                              ? "text-amber-500"
                              : "text-red-500"
                        }`}
                      />
                    </td>
                    <td className="text-foreground px-3 py-2 font-mono text-xs">
                      {isEditingSku ? (
                        <input
                          type="text"
                          value={skuDraft}
                          autoFocus
                          onChange={(e) => setSkuDraft(e.target.value)}
                          onBlur={() => commitSkuEdit(row.rowNumber)}
                          onKeyDown={(e) => {
                            if (e.key === "Enter") {
                              commitSkuEdit(row.rowNumber);
                            } else if (e.key === "Escape") {
                              setEditingRowNumber(null);
                              setSkuDraft("");
                            }
                          }}
                          aria-label={`Editar SKU fila ${row.rowNumber}`}
                          className="border-primary bg-background text-foreground w-36 border px-1.5 py-0.5 font-mono text-xs outline-none"
                        />
                      ) : (
                        <button
                          type="button"
                          onClick={() => {
                            if (!onUpdateRowSku) return;
                            setEditingRowNumber(row.rowNumber);
                            setSkuDraft(row.sku);
                          }}
                          title="Haz clic para editar el SKU"
                          className="hover:text-primary inline-flex items-center gap-1.5 text-left transition-colors"
                        >
                          <span>{row.sku || "—"}</span>
                          {row.skuAutoGenerated && (
                            <StatusPill tone="warning">Sugerido</StatusPill>
                          )}
                        </button>
                      )}
                    </td>
                    <td className="text-foreground max-w-50 truncate px-3 py-2">
                      {row.name || "—"}
                    </td>
                    <td className="text-muted-foreground px-3 py-2 text-xs">
                      {row.categoryRaw ?? "—"}
                    </td>
                    <td className="text-muted-foreground px-3 py-2 text-xs">
                      {row.brandRaw ?? "—"}
                    </td>
                    <td className="text-muted-foreground px-3 py-2 text-xs">
                      {row.cost !== undefined ? `$${row.cost.toFixed(2)}` : "—"}
                    </td>
                    <td className="px-3 py-2">
                      <div className="space-y-1">
                        {row.errors.map((err, eIdx) => (
                          <p
                            key={eIdx}
                            className={`text-xs ${
                              err.severity === "error"
                                ? "text-red-600 dark:text-red-400"
                                : err.severity === "warning"
                                  ? "text-status-warning-fg"
                                  : "text-status-info-fg"
                            }`}
                          >
                            {err.message}
                          </p>
                        ))}
                        {duplicateMatchSku && onUpdateRowSku && (
                          <button
                            type="button"
                            onClick={() =>
                              onUpdateRowSku(row.rowNumber, duplicateMatchSku)
                            }
                            className="border-border bg-background text-foreground hover:bg-muted inline-flex items-center gap-1 border px-2 py-0.5 text-xs font-medium transition-colors"
                          >
                            <Icons.SyncAlt className="size-3" />
                            Vincular a {duplicateMatchSku}
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {paddingBottom > 0 && (
                <tr>
                  <td colSpan={8} style={{ height: `${paddingBottom}px` }} />
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Actions */}
      <div className="flex items-center justify-between">
        <button
          type="button"
          onClick={onBack}
          className="text-muted-foreground hover:text-foreground inline-flex items-center gap-1 text-sm transition-colors"
        >
          <Icons.ArrowBack className="size-4.5" />
          Volver
        </button>

        <button
          type="button"
          onClick={onProceed}
          disabled={processableCount === 0}
          className="bg-primary text-primary-foreground hover:bg-primary/90 inline-flex h-9 items-center gap-2 px-4 text-xs font-medium transition-colors disabled:cursor-not-allowed disabled:opacity-50"
        >
          <Icons.ArrowForward className="size-3.5" />
          Continuar con {processableCount} filas
        </button>
      </div>
    </div>
  );
}
